#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    // p[j]: strings ending in exactly j consecutive vowels.
    vector<long long> p(k + 1, 0), q(k + 1);
    p[0] = 1;
    for (int step = 0; step < n; step++) {
        long long total = 0;
        for (long long v : p) total += v;
        q[0] = total % MOD * 21 % MOD;
        for (int j = 1; j <= k; j++) q[j] = p[j - 1] * 5 % MOD;
        swap(p, q);
    }
    long long total = 0;
    for (long long v : p) total += v;
    printf("%lld\n", total % MOD);
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        final long MOD = 1000000007L;
        // p[j]: strings ending in exactly j consecutive vowels.
        long[] p = new long[k + 1], q = new long[k + 1];
        p[0] = 1;
        for (int step = 0; step < n; step++) {
            long total = 0;
            for (long v : p) total += v;
            q[0] = total % MOD * 21 % MOD;
            for (int j = 1; j <= k; j++) q[j] = p[j - 1] * 5 % MOD;
            long[] t = p; p = q; q = t;
        }
        long total = 0;
        for (long v : p) total += v;
        System.out.println(total % MOD);
    }
}

package main

import "fmt"

const mod = 1000000007

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	// p[j]: strings ending in exactly j consecutive vowels.
	p, q := make([]int64, k+1), make([]int64, k+1)
	p[0] = 1
	for step := 0; step < n; step++ {
		var total int64
		for _, v := range p {
			total += v
		}
		q[0] = total % mod * 21 % mod
		for j := 1; j <= k; j++ {
			q[j] = p[j-1] * 5 % mod
		}
		p, q = q, p
	}
	var total int64
	for _, v := range p {
		total += v
	}
	fmt.Println(total % mod)
}
